 page.locator('#training-custom-add').click();page.locator('#custom-training-title').fill('Exercice libre');page.locator('#custom-training-form button[type=submit]').click();assert page.locator('.training-block').count()==2;page.locator('#training-next').click();assert page.evaluate('trainingLibrary.length')==1
